 test('independent Node process reconstructs Trip and committed receipt from native SQL',async()=>{await setConfig(config());const request=envelope('DISPATCH_TRIP',await fleet()),result=await service.execute('SUPER_ADMIN',scope,request),{spawn}=await import('node:child_process');const script=`import {SqlTripAuthority} from './src/db/tripAuthority.ts';import {closePool} from './src/db/pool.ts';let s='';for await(const c of process.stdin)s+=c;const q=JSON.parse(s);try{const a=new SqlTripAuthority({verifyToken:async()=>({uid:q.uid})});const r=await a.receipt('verified',q.scope,q.op);process.stdout.write(JSON.stringify({trip:r.trip.tripId,committed:r.committed,pid:process.pid}));await closePool();}catch(e){process.stderr.write(String(e.code||'PROBE_FAILED'));process.exit(1);}`;const output=await new Promise<string>((resolve,reject)=>{const child=spawn(process.execPath,['--import','tsx','--input-type=module','-e',script],{cwd:process.cwd(),env:process.env,windowsHide:true});let output='';child.stdout.on('data',d=>output+=d);child.on('error',reject);child.on('exit',code=>code===0?resolve(output):reject(Error('PROBE_FAILED')));child.stdin.end(JSON.stringify({uid:actors.SUPER_ADMIN,scope,op:request.operationId}));});expect(JSON.parse(output)).toMatchObject({trip:result.trip.tripId,committed:true});expect(JSON.parse(output).pid).not.toBe(process.pid);});
 test('isolated v2 HTTP enforces authentication, envelope scope and bounded evidence pages',async()=>{await setConfig(config());const request=envelope('DISPATCH_TRIP',await fleet()),app=express();mountIsolatedSqlTripRoutes(app,service,async()=>company);const server=await new Promise<any>(resolve=>{const s=app.listen(0,'127.0.0.1',()=>resolve(s));}),base=`http://127.0.0.1:${server.address().port}/api/v2/projects/${scope.projectId}`;try{expect((await fetch(base+'/trips/commands',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(request)})).status).toBe(401);const res=await fetch(base+'/trips/commands',{method:'POST',headers:{authorization:'Bearer SUPER_ADMIN','content-type':'application/json'},body:JSON.stringify(request)});expect(res.status).toBe(200);const body=await res.json();expect((await fetch(base+'/trips/'+body.trip.tripId+'/weights?limit=51',{headers:{authorization:'Bearer SUPER_ADMIN'}})).status).toBe(409);expect((await fetch(base+'/trips/operations/'+request.operationId,{headers:{authorization:'Bearer SUPER_ADMIN'}})).status).toBe(200);}finally{await new Promise<void>(r=>server.close(()=>r()));}});

 for(const sourceType of ['EXCEL','GOOGLE_SHEETS','GOOGLE_DRIVE'])test(`reviewed ${sourceType} Trip source uses the trusted immutable verification adapter`,async()=>{const x=await importSession(1,{},sourceType),approved=await reviewImport(x),done=await x.imp.advance('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,operationId:x.s.operationId,requestId:randomUUID(),expectedVersion:approved.operation.version});expect(done.operation.state).toBe('COMPLETED');const trip=(await service.read('SUPER_ADMIN',scope,done.receipts[0].resultSummary.tripId)).trip;expect(trip.source.sourceSha).toMatch(/^[a-f0-9]{64}$/);expect(trip.sourceType).toBe(sourceType);});
 test('TON source unit preserves original raw precision and exact normalized kg',async()=>{const x=await importSession(1,{Tare:'10.000125',Gross:'30.000625',Unit:'TON'}),approved=await reviewImport(x),done=await x.imp.advance('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,operationId:x.s.operationId,requestId:randomUUID(),expectedVersion:approved.operation.version});expect(done.operation.state).toBe('COMPLETED');const trip=(await service.read('SUPER_ADMIN',scope,done.receipts[0].resultSummary.tripId)).trip;expect(trip.weights.originNetKg).toBe('20000.500');});
 test('source entity correction clears resolution and requires an explicit new choice while preserving correction evidence',async()=>{const x=await importSession(),p=await x.imp.tripPreview('SUPER_ADMIN',scope,x.s.sessionId);x.s.version=(await x.imp.tripCorrect('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,requestId:randomUUID(),expectedVersion:x.s.version,corrections:[{sourceRowId:p.rows[0].sourceRowId,field:'truckNo',originalValue:x.refs.truckId,correctedValue:'corrected source truck label',reason:'Reviewed alias correction'}]})).version;await expect(x.imp.tripPreview('SUPER_ADMIN',scope,x.s.sessionId)).rejects.toHaveProperty('code');const cp=await x.imp.readCheckpoint('SUPER_ADMIN',scope,x.s.sessionId);expect(cp.tripBatch.rows[0].resolved.truckId).toBeUndefined();cp.tripBatch.rows[0].resolved.truckId=x.refs.truckId;x.s.version=(await x.imp.tripCheckpoint('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,requestId:randomUUID(),expectedVersion:x.s.version,mapping:{mappingRevisionId:cp.mapping.mappingRevisionId,sourceRevisionId:x.s.sourceRevisionId,mappings:cp.mapping.mappings,approved:true},rows:cp.tripBatch.rows})).version;expect((await x.imp.readCheckpoint('SUPER_ADMIN',scope,x.s.sessionId)).tripCorrections).toHaveLength(1);expect((await reviewImport(x)).operation.state).toBe('READY');});
 test('PER_TRIP NO_WEIGHBRIDGE completes without quantity and uses exact rounded rate plus VAT',async()=>{await setConfig(config('NO_WEIGHBRIDGE'));const m=await make('MATERIAL');await price('FLAT-NO-SCALE',{materialId:m.externalId,pricingType:'PER_TRIP',rate:'125.1250'});const f=await fleet();await canonical.allocation('SUPER_ADMIN',{...scope,operationId:randomUUID(),command:'REALLOCATE',truckId:f.truckId,materialId:m.externalId});let trip=(await service.execute('SUPER_ADMIN',scope,envelope('DISPATCH_TRIP',{...f,materialId:m.externalId,pricingRuleId:'FLAT-NO-SCALE'}))).trip;trip=await cmd(trip,'START_TRANSIT');trip=await cmd(trip,'RECORD_ARRIVAL');trip=await cmd(trip,'COMPLETE_UNLOADING');trip=await cmd(trip,'COMPLETE_TRIP');expect(trip.financials.status).toBe('FINAL');expect(trip.financials.quantity_kg).toBeNull();expect(trip.financials.base_amount).toBe('125.13');expect(trip.financials.tax).toBe('18.77');expect(trip.financials.final_amount).toBe('143.90');});
 for(const rate of ['0','-1','NaN'])test(`invalid final commercial rate ${rate} cannot become zero-price settlement`,async()=>{await expect(withUnitOfWork({companyId:company,projectId:project,actorId:actors.SUPER_ADMIN},uow=>new TripSettlementRepository(uow).calculate({pricingType:'PER_TRIP',rate},null),runtime)).rejects.toHaveProperty('code');});
 test('missing demurrage tariff and NUMERIC overflow fail closed without fake amounts',async()=>{await expect(withUnitOfWork({companyId:company,projectId:project,actorId:actors.SUPER_ADMIN},uow=>new TripSettlementRepository(uow).calculate({pricingType:'PER_TRIP',rate:'10'},null,'2'),runtime)).rejects.toMatchObject({code:'DEMURRAGE_TERMS_REQUIRED'});await expect(withUnitOfWork({companyId:company,projectId:project,actorId:actors.SUPER_ADMIN},uow=>new TripSettlementRepository(uow).calculate({pricingType:'PER_TON',rate:'999999999999'},'999999999999'),runtime)).rejects.toMatchObject({code:'COMMERCIAL_NUMERIC_LIMIT'});});

 test('approved unit correction retains original raw unit and signed correction provenance',async()=>{const x=await importSession(1,{Tare:'10',Gross:'30',Unit:'KG'}),p=await x.imp.tripPreview('SUPER_ADMIN',scope,x.s.sessionId);x.s.version=(await x.imp.tripCorrect('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,requestId:randomUUID(),expectedVersion:x.s.version,corrections:[{sourceRowId:p.rows[0].sourceRowId,field:'sourceUnit',originalValue:'KG',correctedValue:'TON',reason:'Reviewed original unit error'}]})).version;const approved=await reviewImport(x),done=await x.imp.advance('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,operationId:x.s.operationId,requestId:randomUUID(),expectedVersion:approved.operation.version});expect(done.operation.state).toBe('COMPLETED');const trip=(await service.read('SUPER_ADMIN',scope,done.receipts[0].resultSummary.tripId)).trip;expect(trip.weights.originNetKg).toBe('20000.000');const record=(await admin.query('SELECT raw_value,source_unit,source_correction FROM trip_weight_records WHERE id=$1',[trip.measurementIds.origin.TARE])).rows[0];expect(record.raw_value).toBe('10');expect(record.source_unit).toBe('KG');expect(record.source_correction[0]).toMatchObject({originalValue:'KG',correctedValue:'TON'});});
 test('archived cleanup may deactivate an orphaned rule without allowing commercial amendment',async()=>{const c=await make('CARRIER');await price('CLEANUP',{carrierId:c.externalId});await admin.query("UPDATE project_carriers SET status='REMOVED' WHERE company_id=$1 AND project_id=$2 AND carrier_id=$3",[company,project,c.id]);await admin.query("UPDATE projects SET status='ARCHIVED' WHERE id=$1",[project]);try{expect((await price('CLEANUP',{carrierId:c.externalId,status:'INACTIVE'},'CLEANUP',1)).status).toBe('INACTIVE');const before=await counts();await expect(price('CLEANUP',{carrierId:c.externalId,rate:'20',status:'INACTIVE'},'CLEANUP',2)).rejects.toHaveProperty('code');expect(await counts()).toEqual(before);}finally{await admin.query("UPDATE projects SET status='SETUP' WHERE id=$1",[project]);}});

 for(const ticket of ['', 'T-REPEATED-SOURCE'])test(`new source revision cannot reimport an accepted physical row (${ticket?'ticket fence':'content/row fence'})`,async()=>{const first=await importSession(1,{Ticket:ticket}),a=await reviewImport(first);const accepted=await first.imp.advance('SUPER_ADMIN',scope,{sessionId:first.s.sessionId,operationId:first.s.operationId,requestId:randomUUID(),expectedVersion:a.operation.version});expect(accepted.operation.state).toBe('COMPLETED');const second=await importSession(1,{Ticket:ticket},'CSV',first.refs),b=await reviewImport(second),before=await counts(),counter=(await admin.query('SELECT next_number FROM trip_number_counters WHERE company_id=$1 AND project_id=$2',[company,project])).rows[0].next_number;const rejected=await second.imp.advance('SUPER_ADMIN',scope,{sessionId:second.s.sessionId,operationId:second.s.operationId,requestId:randomUUID(),expectedVersion:b.operation.version});expect(rejected.operation.state).toBe('REVIEW_REQUIRED');const after=await counts();for(const k of ['trips','trip_events','trip_weight_records','pricing_snapshots','trip_settlements','receipts'])expect(after[k]).toBe(before[k]);expect((await admin.query('SELECT next_number FROM trip_number_counters WHERE company_id=$1 AND project_id=$2',[company,project])).rows[0].next_number).toBe(counter);});
 test('import retains textual ticket/legacy serial identity including leading zeroes',async()=>{const x=await importSession(1,{Ticket:'000456',Serial:'000123'}),approved=await reviewImport(x),done=await x.imp.advance('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,operationId:x.s.operationId,requestId:randomUUID(),expectedVersion:approved.operation.version});expect(done.operation.state).toBe('COMPLETED');const trip=(await service.read('SUPER_ADMIN',scope,done.receipts[0].resultSummary.tripId)).trip;expect(trip.sourceMetadata.legacyTripSerial).toBe('000123');expect(trip.sourceMetadata.sourceTicketId).toBe('000456');expect(trip.weights.originTicketNo).toBe('000456');expect(trip.weights.destinationTicketNo).toBeUndefined();});

 test('a tariff first used by late pending settlement requires copy-on-write on amendment',async()=>{
  const x=await importSession(1,{Dest:'19999'}),m=await make('MATERIAL');
  await canonical.allocation('SUPER_ADMIN',{...scope,operationId:randomUUID(),command:'REALLOCATE',truckId:x.refs.truckId,materialId:m.externalId});
  const cp=await x.imp.readCheckpoint('SUPER_ADMIN',scope,x.s.sessionId),rows=cp.tripBatch.rows.map((r:any)=>({...r,resolved:{...r.resolved,materialId:m.externalId,pricingRuleId:null}}));
  x.s.version=(await x.imp.tripCheckpoint('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,requestId:randomUUID(),expectedVersion:x.s.version,mapping:{mappingRevisionId:randomUUID(),sourceRevisionId:x.s.sourceRevisionId,mappings:cp.mapping.mappings,approved:true},rows})).version;
  const approved=await reviewImport(x),done=await x.imp.advance('SUPER_ADMIN',scope,{sessionId:x.s.sessionId,operationId:x.s.operationId,requestId:randomUUID(),expectedVersion:approved.operation.version});let trip=(await service.read('SUPER_ADMIN',scope,done.receipts[0].resultSummary.tripId)).trip;
  await price('LATE-FIRST-USE',{materialId:m.externalId,rate:'8'});trip=await cmd(trip,'SETTLE_PRICING',{reason:'Approve original historical tariff'},'FINANCE_AUDITOR');expect(trip.financials.base_amount).toBe('159.99');
  const before=(await admin.query('SELECT * FROM trip_settlements WHERE id=$1',[trip.financials.settlementId])).rows[0];
  const successor=await price('LATE-FIRST-USE',{materialId:m.externalId,rate:'9',effectiveFrom:'2036-01-01'},'LATE-FIRST-USE',1);expect(successor.parentRuleId).toBe('LATE-FIRST-USE');expect(successor.pricingRuleId).not.toBe('LATE-FIRST-USE');
  expect((await admin.query('SELECT * FROM trip_settlements WHERE id=$1',[trip.financials.settlementId])).rows[0]).toEqual(before);expect((await service.read('SUPER_ADMIN',scope,trip.tripId)).trip.pricingSnapshot.rate).toBe('8');
 });

